// Generates supabase/seed.sql from the shared DEMO network so both stay in sync.
// Run: npx tsx scripts/gen-seed.ts > supabase/seed.sql
import { buildDemoNetwork } from '../packages/shared/src/demo-data';

const q = (v: unknown) => (v === undefined || v === null ? 'null' : typeof v === 'number' || typeof v === 'boolean' ? String(v) : `'${String(v).replace(/'/g, "''")}'`);
const arr = (a: string[]) => `array[${a.map(q).join(',')}]::text[]`;

const lines: string[] = [
  '-- DEMO seed data (generated by scripts/gen-seed.ts). Every row is flagged is_demo / is_simulated.',
  '-- Load only in development/staging, never in production.',
  'begin;',
];
for (const s of buildDemoNetwork()) {
  lines.push(
    `insert into public.stations (id, owner_id, name, address, city, lat, lng, listing_status, opening_hours, is_24h, access, amenities, deal, is_demo, source) values (${[q(s.id), 'null', q(s.name), q(s.address), q(s.city), s.lat, s.lng, q(s.listingStatus), q(s.openingHours), s.is24h, q(s.access), arr(s.amenities), s.deal ? `'${JSON.stringify(s.deal).replace(/'/g, "''")}'::jsonb` : 'null', 'true', q('demo')].join(', ')}) on conflict (id) do nothing;`,
  );
  for (const t of s.tariffs) lines.push(`insert into public.tariffs (id, station_id, price_per_kwh, idle_fee_per_min, idle_grace_min) values (${[q(t.id), q(s.id), t.pricePerKwh, q(t.idleFeePerMin), q(t.idleGraceMin)].join(', ')}) on conflict (id) do nothing;`);
  for (const c of s.chargers) lines.push(`insert into public.chargers (id, station_id, ocpp_identity, vendor, model, is_simulated, commissioned) values (${[q(c.id), q(s.id), q(c.ocppIdentity), q(c.vendor), q(c.model), 'true', c.commissioned].join(', ')}) on conflict (id) do nothing;`);
  for (const k of s.connectors)
    lines.push(
      `insert into public.connectors (id, charger_id, station_id, ocpp_connector_id, label, type, current_type, power_kw, status, tariff_id) values (${[q(k.id), q(k.chargerId), q(s.id), k.ocppConnectorId, q(k.label), q(k.type), q(k.current), k.powerKw, q('Unknown'), q(k.tariffId)].join(', ')}) on conflict (id) do nothing;`,
    );
}
lines.push('commit;');
console.log(lines.join('\n'));
